-- Brownstone catalogue, generated by scripts/export-catalog-sql.mjs.
-- Safe to reapply; keeps all existing residents, layouts, unlocks and reactions.
BEGIN;
WITH rows AS (
 SELECT string_to_array(line,'|') AS v, n-1 AS ordinal
 FROM unnest(string_to_array($catalog$floor-cushion|1|standard||floor|1|3||
succulent-pot|1|standard||sill,floor|1|3||
wooden-stool|1|standard||floor|1|3||
plain-curtains|1|standard||window|3|3||
paper-lantern|1|standard||ceiling|1|3||
