mountain-poster|1|standard||wall|1|3||
wall-clock|1|standard||wall|1|3||
crate-shelf|1|standard||floor|2|3||
side-table|1|standard||floor|1|3||
floor-lamp|1|standard||floor|1|3||
eucalyptus-garland|1|standard||wallTop|3|2||
comfy-sofa|2|standard||floor|3|4||
armchair|2|standard||floor|2|4||
monstera|2|standard||floor|1|3||
hanging-pothos|2|standard||ceiling|1|3||
floral-curtains|2|standard||window|3|3||
gallery-trio|2|standard||wall|2|3||
tall-bookshelf|2|standard||floor|2|3||
arc-lamp|2|standard||floor|2|3||
striped-rug|2|standard||rug|3|3||
tiny-tv|2|standard||floor|1|3||
pet-bed|2|standard||floor|1|3||
wall-shelf|2|standard||wall|2|3||
yarn-basket|2|standard||floor|1|3||
record-player|3|standard||floor|1|3||
tiny-aquarium|3|standard||floor|1|3||
canopy-bed|3|standard||floor|3|3||
fairy-lights|3|standard||wallTop|3|3||
garden-door|3|standard||floor|2|3||
lava-lamp|3|standard||floor,sill|1|3||
fireplace|3|standard||floor|3|3||
globe-chandelier|3|standard||ceiling|2|2||
egg-chair|3|standard||floor|2|3||
telescope|3|standard||floor|1|3||
pumpkin|1|seasonal||floor,sill|1|3|9|11
tiny-tree|1|seasonal||floor|1|2|12|1
dried-roses|1|seasonal||sill,floor|1|2|2|2
blossom-vase|1|seasonal||sill,floor|1|3|3|5
summer-fan|1|seasonal||floor,sill|1|2|6|8
neon-moon|3|surprise||wall|1|2||
snail-terrarium|3|surprise||sill,floor|1|2||
candle-cluster|1|standard||sill,floor|1|3||
bar-cart|2|standard||floor|2|2||
pressed-flowers|1|standard||wall|1|3||
postcard-string|1|standard||wall|2|3||
woven-wall-hanging|1|standard||wall|1|3||
scalloped-mirror|2|standard||wall|1|3||
cuckoo-clock|2|standard||wall|1|3||
quilt-bunting|2|standard||wallTop|3|3||
velvet-drapes|3|standard||window|1|3||
walnut-shutters|2|standard||window|1|3||
roller-blind|1|standard||window|1|3||
cafe-curtain|2|standard||window|1|3||
wingback-chair|2|standard||floor|2|4||
peacock-chair|3|standard||floor|2|3||
spindle-daybed|3|standard||floor|3|3||
chaise-longue|3|standard||floor|3|4||
upright-piano|3|standard||floor|3|3||
artists-easel|3|standard||floor|3|3||
built-in-bookcase|3|standard||floor|3|3||
gilt-mirror|2|standard||wall|1|3||
pleated-pendant|2|standard||ceiling|1|3||
wicker-pendant|2|standard||ceiling|1|3||
pierced-lantern|3|standard||ceiling|1|3||
wall-sconce|2|standard||wall|1|3||
plain-paper|1|starter|wallpaper|||||
bare-boards|1|starter|flooring|||||
soft-stripes|1|standard|wallpaper|||||
warm-planks|1|standard|flooring|||||
polka-dots|2|standard|wallpaper|||||
mint-gingham|2|standard|wallpaper|||||
checker-tiles|2|standard|flooring|||||
starry-night|3|standard|wallpaper|||||
scallop-shells|3|standard|wallpaper|||||
vine-trellis|3|standard|wallpaper|||||
herringbone|3|standard|flooring|||||
terrazzo|3|standard|flooring|||||
paint-bottle-green|1|standard|wallpaper|||||
paint-oxblood|1|standard|wallpaper|||||
paint-terracotta|1|standard|wallpaper|||||
paint-navy|1|standard|wallpaper|||||
paint-ochre|1|standard|wallpaper|||||
paint-plum|1|standard|wallpaper|||||
clay-tiles|2|standard|flooring|||||
painted-boards|2|standard|flooring|||||
dark-parquet|2|standard|flooring|||||$catalog$,E'\n')) WITH ORDINALITY AS r(line,n)
)
INSERT INTO flats_private.catalog(id,ordinal,data)
SELECT v[1],ordinal,jsonb_strip_nulls(jsonb_build_object(
 'id',v[1],'tier',v[2]::int,'rarity',v[3],'kind',nullif(v[4],''),
 'zones',CASE WHEN v[5]<>'' THEN to_jsonb(string_to_array(v[5],',')) END,
 'size',nullif(v[6],'')::int,'paletteCount',nullif(v[7],'')::int,
 'season',CASE WHEN v[8]<>'' THEN jsonb_build_object('from',v[8]::int,'to',v[9]::int) END)) FROM rows
ON CONFLICT(id) DO UPDATE SET ordinal=excluded.ordinal,data=excluded.data;
COMMIT;
SELECT count(*) AS catalogue_entries, count(*) FILTER(WHERE data ? 'zones') AS things,
 count(*) FILTER(WHERE data ? 'kind') AS surfaces FROM flats_private.catalog;
